using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using SaaSFoundry.EngineeringWorkbench.Core.Contracts.BackgroundJobs;

namespace VibeStock.System.Cell.Generated.BackgroundProcessing;

public class BackgroundWorkerService : BackgroundService
{
    private readonly IServiceProvider _serviceProvider;
    private readonly ILogger<BackgroundWorkerService> _logger;
    private readonly TimeSpan _pollingDelay = TimeSpan.FromSeconds(5);
    private const int MaxAttempts = 3;

    public BackgroundWorkerService(
        IServiceProvider serviceProvider,
        ILogger<BackgroundWorkerService> logger)
    {
        _serviceProvider = serviceProvider;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("BackgroundWorkerService is starting.");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _serviceProvider.CreateScope();
                var jobStorage = scope.ServiceProvider.GetRequiredService<IJobStorageCapability>();
                
                var job = await jobStorage.ClaimNextAsync(stoppingToken);

                if (job == null)
                {
                    // No job available, wait before polling again
                    await Task.Delay(_pollingDelay, stoppingToken);
                    continue;
                }

                await ProcessJobAsync(job, scope.ServiceProvider, stoppingToken);
            }
            catch (OperationCanceledException)
            {
                // Graceful cancellation
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred in the background worker loop.");
                // Prevent tight loop on database failure
                await Task.Delay(_pollingDelay, stoppingToken);
            }
        }

        _logger.LogInformation("BackgroundWorkerService is stopping.");
    }

    private async Task ProcessJobAsync(EnqueuedJob job, IServiceProvider scopedProvider, CancellationToken stoppingToken)
    {
        var jobStorage = scopedProvider.GetRequiredService<IJobStorageCapability>();
        var contextSerializer = scopedProvider.GetRequiredService<IJobContextSerializer>();
        var dispatcher = scopedProvider.GetRequiredService<IJobDispatcher>();

        _logger.LogInformation("Processing job {JobId} of type {JobTypeId}", job.JobId, job.JobTypeId);

        try
        {
            var context = contextSerializer.Deserialize(job.SerializedContext);
            await dispatcher.DispatchAsync(job, context, scopedProvider, stoppingToken);
            
            await jobStorage.CompleteAsync(job.JobId, stoppingToken);
            _logger.LogInformation("Successfully completed job {JobId}", job.JobId);
        }
        catch (OperationCanceledException)
        {
            _logger.LogWarning("Job {JobId} was cancelled.", job.JobId);
            await jobStorage.CancelAsync(job.JobId, CancellationToken.None);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to execute job {JobId}", job.JobId);
            
            var failureInfo = new JobFailureInformation(
                ex.Message,
                ex.StackTrace,
                DateTimeOffset.UtcNow
            );

            if (job.AttemptCount < MaxAttempts)
            {
                // Simple retry policy: add 1 minute per attempt
                var nextExecutionTime = DateTimeOffset.UtcNow.AddMinutes(job.AttemptCount);
                await jobStorage.RetryAsync(job.JobId, failureInfo, nextExecutionTime, stoppingToken);
                _logger.LogInformation("Job {JobId} scheduled for retry at {NextExecutionTime}", job.JobId, nextExecutionTime);
            }
            else
            {
                await jobStorage.FailAsync(job.JobId, failureInfo, stoppingToken);
                _logger.LogError("Job {JobId} permanently failed after {AttemptCount} attempts", job.JobId, job.AttemptCount);
            }
        }
    }
}